pub export fn max_consecutive_ones_iii(a:[*c]const i64,len:usize)i64{if(a==null or len<3 or len>1026)return -2;if(a[0]<1 or a[0]>1024 or len!=@as(usize,@intCast(a[0]))+2 or a[1]<0 or a[1]>a[0])return -2;const n:usize=@intCast(a[0]);for(0..n)|i|if(a[i+2]!=0 and a[i+2]!=1)return -2;var l:usize=0;var z:usize=0;var b:usize=0;for(0..n)|r|{if(a[r+2]==0)z+=1;while(z>@as(usize,@intCast(a[1]))){if(a[l+2]==0)z-=1;l+=1;}b=@max(b,r-l+1);}return @intCast(b);}
